import React, { useState } from 'react';
import axios from 'axios';
import Navbar from './components/Navbar.jsx';
import Home from './components/Home.jsx';
import Timetable from './components/Timetable.jsx';
import About from './components/About.jsx';
import LmsDashboard from './components/LmsDashboard.jsx'; 
import StudentDashboard from './components/StudentDashboard.jsx';
import TeacherDashboard from './components/TeacherDashboard.jsx';
import Footer from './components/Footer.jsx';
import Login from './components/Login.jsx';

export default function App() {
  const [currentPage, setCurrentPage] = useState('Home');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [userRole, setUserRole] = useState(null); 
  const [userName, setUserName] = useState('User');
  const [userId, setUserId] = useState(null); 

  const isDashboard = isLoggedIn && currentPage === 'Dashboard';

  const handleLoginSubmit = async (username, password) => {
    try {
      const response = await axios.post('http://localhost:8081/login', {
        username: username,
        password: password
      });

      if (response.data.status === "Success") {
        setIsLoggedIn(true);
        setUserRole(response.data.role); 
        setUserName(response.data.name); 
        setUserId(response.data.id);     
        setCurrentPage('Dashboard'); 
        setShowLoginModal(false);
      } else {
        alert(`❌ Login Failed: ${response.data.message || "Invalid Username or Password!"}`);
      }
    } catch (error) {
      alert("❌ Login Failed: Cannot connect to the server!");
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setUserRole(null);
    setUserName('User');
    setUserId(null);
    setCurrentPage('Home');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      
      {!isDashboard && (
        <Navbar 
           onLoginClick={() => setShowLoginModal(true)} 
           isLoggedIn={isLoggedIn} 
           userName={userName}
           setCurrentPage={setCurrentPage} 
           currentPage={currentPage}
        />
      )}

      <main style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
        {currentPage === 'Home' && <Home />}
        {currentPage === 'Classes' && <Timetable />}
        {currentPage === 'About' && <About />}
        
        {currentPage === 'Dashboard' && isLoggedIn && (
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column' }}>
            {userRole === 'admin' && <LmsDashboard userName={userName} handleLogout={handleLogout} />}
            {userRole === 'teacher' && <TeacherDashboard userName={userName} userId={userId} handleLogout={handleLogout} />}
            {userRole === 'student' && <StudentDashboard userName={userName} userId={userId} handleLogout={handleLogout} />}
          </div>
        )}
      </main>

      {!isDashboard && <Footer />}

      {showLoginModal && (
        <Login 
          setShowLoginModal={setShowLoginModal} 
          handleLoginSubmit={handleLoginSubmit} 
        />
      )}
    </div>
  );
}
